package provider_test

import (
	"context"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/datasource"
	dsschema "github.com/hashicorp/terraform-plugin-framework/datasource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	rschema "github.com/hashicorp/terraform-plugin-framework/resource/schema"

	"bitbucket.org/atlanticbt/terraform-provider-nodeping/internal/provider"
)

// The reference pages under docs/ are hand-written rather than generated by
// tfplugindocs, because they carry prose that a generator would discard — the
// ad-hoc maintenance recipe, the address-ID-versus-contact-ID explanation, the
// import guidance. Hand-written docs drift silently as schemas change, so this
// test fails the build when an attribute exists in a schema but appears nowhere
// in its documentation page.
//
// It deliberately checks only for *presence*. It cannot tell whether the prose
// is accurate, only whether an attribute was forgotten entirely. Migrating to
// tfplugindocs with templates that preserve the prose would be strictly better
// and is tracked in docs/roadmap.md.

// Attributes that are intentionally undocumented, with the reason. Keep this
// list short; an entry here is a decision, not a backlog item.
var undocumentedByDesign = map[string]string{
	// Nothing currently. Add as "resource.attribute": "reason".
}

func TestDocsCoverEveryResourceAttribute(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	for _, ctor := range provider.New("test")().Resources(ctx) {
		res := ctor()

		var meta resource.MetadataResponse
		res.Metadata(ctx, resource.MetadataRequest{ProviderTypeName: "nodeping"}, &meta)

		var schemaResp resource.SchemaResponse
		res.Schema(ctx, resource.SchemaRequest{}, &schemaResp)

		t.Run(meta.TypeName, func(t *testing.T) {
			t.Parallel()
			doc := readDoc(t, filepath.Join("..", "..", "docs", "resources", meta.TypeName+".md"))
			names := resourceAttributeNames(schemaResp.Schema)
			assertDocumented(t, meta.TypeName, names, doc)
		})
	}
}

func TestDocsCoverEveryDataSourceAttribute(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	for _, ctor := range provider.New("test")().DataSources(ctx) {
		ds := ctor()

		var meta datasource.MetadataResponse
		ds.Metadata(ctx, datasource.MetadataRequest{ProviderTypeName: "nodeping"}, &meta)

		var schemaResp datasource.SchemaResponse
		ds.Schema(ctx, datasource.SchemaRequest{}, &schemaResp)

		t.Run(meta.TypeName, func(t *testing.T) {
			t.Parallel()
			doc := readDoc(t, filepath.Join("..", "..", "docs", "data-sources", meta.TypeName+".md"))
			names := dataSourceAttributeNames(schemaResp.Schema)
			assertDocumented(t, meta.TypeName, names, doc)
		})
	}
}

func readDoc(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("documentation page missing: %v", err)
	}
	return string(b)
}

func assertDocumented(t *testing.T, typeName string, names []string, doc string) {
	t.Helper()
	for _, name := range names {
		if reason, ok := undocumentedByDesign[typeName+"."+name]; ok {
			t.Logf("%s.%s intentionally undocumented: %s", typeName, name, reason)
			continue
		}
		// Match the attribute as a whole word so `port` does not satisfy
		// `dport`, and so a mention inside a longer identifier does not count.
		re := regexp.MustCompile(`\b` + regexp.QuoteMeta(name) + `\b`)
		if !re.MatchString(doc) {
			t.Errorf("%s: attribute %q is in the schema but not mentioned in its documentation page", typeName, name)
		}
	}
}

// resourceAttributeNames collects top-level attribute and block names plus one
// level of nesting. Deeper nesting is rare here and the extra traversal is not
// worth the reflection complexity.
func resourceAttributeNames(s rschema.Schema) []string {
	var out []string
	for name, attr := range s.Attributes {
		out = append(out, name)
		if nested, ok := attr.(rschema.NestedAttribute); ok {
			for child := range nested.GetNestedObject().GetAttributes() {
				out = append(out, child)
			}
		}
	}
	for name, blk := range s.Blocks {
		out = append(out, name)
		for child := range blk.GetNestedObject().GetAttributes() {
			out = append(out, child)
		}
	}
	return dedupe(out)
}

func dataSourceAttributeNames(s dsschema.Schema) []string {
	var out []string
	for name, attr := range s.Attributes {
		out = append(out, name)
		if nested, ok := attr.(dsschema.NestedAttribute); ok {
			for child := range nested.GetNestedObject().GetAttributes() {
				out = append(out, child)
			}
		}
	}
	for name, blk := range s.Blocks {
		out = append(out, name)
		for child := range blk.GetNestedObject().GetAttributes() {
			out = append(out, child)
		}
	}
	return dedupe(out)
}

func dedupe(in []string) []string {
	seen := make(map[string]struct{}, len(in))
	out := in[:0]
	for _, s := range in {
		if s == "" || strings.HasPrefix(s, "_") {
			continue
		}
		if _, ok := seen[s]; ok {
			continue
		}
		seen[s] = struct{}{}
		out = append(out, s)
	}
	return out
}
